import itertools

def extendable(n, edges, fixed):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    colors = [-1] * n
    for v, c in fixed.items():
        colors[v] = c
    for u, v in edges:
        if colors[u] != -1 and colors[v] != -1 and colors[u] == colors[v]:
            return False
    order = [v for v in range(n) if colors[v] == -1]
    def bt(idx):
        if idx == len(order):
            return True
        v = order[idx]
        for c in range(3):
            if all(colors[j] != c for j in adj[v]):
                colors[v] = c
                if bt(idx + 1):
                    return True
                colors[v] = -1
        return False
    return bt(0)

for k in (1, 2, 3):
    fixed = 4
    n = fixed + k
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n) if i >= fixed or j >= fixed]
    found = False
    for mask in range(1 << len(pairs)):
        edges = [pairs[t] for t in range(len(pairs)) if mask >> t & 1]
        ok = True
        for c in itertools.product((0, 1), repeat=3):
            fc = {0: c[0], 1: c[1], 2: c[2], 3: 2}
            res = extendable(n, edges, fc)
            want = (c != (1, 1, 1))
            if res != want:
                ok = False
                break
        if ok:
            print("k=", k, "FOUND edges:", edges)
            found = True
            break
    if not found:
        print("k=", k, "none")
