import itertools

def extendable(n, edges, fixed):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v); adj[v].append(u)
    colors = [-1] * n
    for v, c in fixed.items():
        colors[v] = c
    for u, v in edges:
        if colors[u] != -1 and colors[v] != -1 and colors[u] == colors[v]:
            return False
    order = [v for v in range(n) if colors[v] == -1]
    def bt(idx):
        if idx == len(order): return True
        v = order[idx]
        for c in range(3):
            if all(colors[j] != c for j in adj[v]):
                colors[v] = c
                if bt(idx+1): return True
                colors[v] = -1
