import itertools, sys
sys.setrecursionlimit(10000)

# fixed vertices: 0,1,2 literals; 3,4,5 complements; 6=T(1),7=F(0),8=B(2)
FIX = 9

def build_sat(k):
    # candidate edges: aux-aux, aux-fixed
    cand = []
    for i in range(FIX, FIX+k):
        for j in range(i+1, FIX+k):
            cand.append((i,j))
        for j in range(FIX):
            cand.append((i,j))
    idx = {e:t for t,e in enumerate(cand)}
    nv = len(cand)
    clauses = []
    # colorings of aux
    colorings = list(itertools.product(range(3), repeat=k))
    # fixed colors per input
    inputs = list(itertools.product((0,1), repeat=3))
    def fixed_colors(b):
        c = [0]*FIX
        for i in range(3):
            c[i] = 1 if b[i] else 0
            c[i+3] = 0 if b[i] else 1
        c[6],c[7],c[8] = 1,0,2
        return c
    # selectors
    sel = {}
    for s,b in enumerate(inputs):
        for ci in range(len(colorings)):
            sel[(s,ci)] = nv; nv += 1
    for s,b in enumerate(inputs):
        fc = fixed_colors(b)
        if b == (0,0,0):
            # all-F: for every aux coloring, at least one violated present edge
            for ci,col in enumerate(colorings):
                full = fc + list(col)
                viol = [idx[e] for e in cand if full[e[0]]==full[e[1]]]
                if not viol:
                    return None  # this coloring always valid -> impossible
                clauses.append(viol)
        else:
            ors = []
            for ci,col in enumerate(colorings):
                full = fc + list(col)
                viol = [idx[e] for e in cand if full[e[0]]==full[e[1]]]
                y = sel[(s,ci)]
                ors.append(y)
                for t in viol:
                    clauses.append([-y, -t])
            clauses.append(ors)
    return cand, nv, clauses

def dpll(clauses, nv):
    # simple DPLL with unit propagation
    assign = {}
    def simplify(cls):
        # returns simplified clauses or None if conflict
        out = []
        for c in cls:
            nc = []
            sat = False
            for l in c:
                v = abs(l); s = l>0
                if v in assign:
                    if assign[v]==s: sat=True; break
                else:
