import itertools

def analyze(k, use_complements=True, use_palette=True):
    # fixed vertices: 0,1,2 literals; 3,4,5 complements; 6=T(1),7=F(0),8=B(2)
    FIX = 6 + (3 if use_palette else 0)
    cand = []
    for i in range(FIX, FIX+k):
        for j in range(i+1, FIX+k):
            cand.append((i,j))
        for j in range(FIX):
            cand.append((i,j))
    cand = list(dict.fromkeys(cand))
    E = len(cand)
    full = (1<<E) - 1
    colorings = list(itertools.product(range(3), repeat=k))
    inputs = list(itertools.product((0,1), repeat=3))
    def fc_of(b):
        c=[0]*FIX
        for i in range(3):
            c[i]=1 if b[i] else 0
            c[i+3]=0 if b[i] else 1
        if use_palette:
            c[6],c[7],c[8]=1,0,2
        return c
    M = {}
    for b in inputs:
        fc=fc_of(b)
        masks=set()
        for col in colorings:
            fullc=fc+list(col)
            m=0
            for t,(u,v) in enumerate(cand):
                if fullc[u]==fullc[v]:
                    m|=(1<<t)
            masks.add(m)
        M[b]=masks
    b0=(0,0,0)
    if any(m==0 for m in M[b0]):
        return None, "all-zero colorable for some coloring -> impossible"
